$panel = 'rounded-2xl border border-slate-200 bg-white shadow-sm shadow-slate-200/60';
?>

<div class="space-y-7">
    <div class="flex flex-col gap-2 border-b border-slate-200 pb-6 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-[11px] font-bold uppercase tracking-[0.18em] text-orange-600">Kinh doanh</p><h2 class="mt-2 text-2xl font-bold tracking-tight text-slate-950 sm:text-3xl">Tổng quan vận hành</h2></div><p class="text-sm text-slate-500">Đơn đã hủy không được tính doanh thu.</p></div>

    <section class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <article class="rounded-2xl bg-blue-950 p-5 text-white shadow-lg shadow-blue-950/15"><div class="flex items-start justify-between gap-3"><span class="text-sm text-blue-200">Doanh thu thực ghi nhận</span><span class="material-symbols-outlined text-blue-200" aria-hidden="true">payments</span></div><strong class="mt-6 block truncate text-2xl font-bold"><?= ViewHelper::money((int)$metrics['revenue']) ?></strong></article>
        <article class="<?= $panel ?> p-5"><div class="flex items-start justify-between gap-3"><span class="text-sm text-slate-500">Đơn có doanh thu</span><span class="flex size-9 items-center justify-center rounded-lg bg-emerald-50 text-emerald-700"><span class="material-symbols-outlined text-[19px]" aria-hidden="true">receipt_long</span></span></div><strong class="mt-6 block text-2xl font-bold text-slate-950"><?= (int)$metrics['orders'] ?></strong></article>
        <article class="<?= $panel ?> p-5"><div class="flex items-start justify-between gap-3"><span class="text-sm text-slate-500">Sách trong kho</span><span class="flex size-9 items-center justify-center rounded-lg bg-orange-50 text-orange-700"><span class="material-symbols-outlined text-[19px]" aria-hidden="true">menu_book</span></span></div><strong class="mt-6 block text-2xl font-bold text-slate-950"><?= (int)($bookCount ?? 0) ?></strong></article>
        <article class="<?= $panel ?> p-5"><div class="flex items-start justify-between gap-3"><span class="text-sm text-slate-500">Khách hàng</span><span class="flex size-9 items-center justify-center rounded-lg bg-violet-50 text-violet-700"><span class="material-symbols-outlined text-[19px]" aria-hidden="true">group</span></span></div><strong class="mt-6 block text-2xl font-bold text-slate-950"><?= (int)($customerCount ?? 0) ?></strong></article>
    </section>

    <?php $table = function (array $headers, array $rows): void { ?>
        <div class="overflow-x-auto"><table class="w-full min-w-[560px] border-collapse text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-[0.1em] text-slate-500"><tr><?php foreach ($headers as $header): ?><th class="px-4 py-3.5 font-bold"><?= $header ?></th><?php endforeach; ?></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($rows as $row): ?><tr class="text-slate-700"><?php foreach ($row as $cell): ?><td class="px-4 py-3.5"><?= $cell ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div>
    <?php }; ?>

    <div class="grid gap-6 xl:grid-cols-2">
        <section class="<?= $panel ?> overflow-hidden"><div class="border-b border-slate-200 px-5 py-5"><p class="text-[11px] font-bold uppercase tracking-[0.15em] text-slate-500">30 ngày gần nhất</p><h3 class="mt-1 text-lg font-bold text-slate-950">Doanh thu theo ngày</h3></div><?php if (empty($metrics['daily'])): ?><p class="p-5 text-sm text-slate-500">Chưa có dữ liệu doanh thu.</p><?php else: ?><?php $rows = []; foreach ($metrics['daily'] as $row) { $rows[] = [ViewHelper::escape($row['period']), (int)$row['orders'], ViewHelper::money((int)$row['revenue'])]; } $table(['Ngày', 'Đơn', 'Doanh thu'], $rows); ?><?php endif; ?></section>
        <section class="<?= $panel ?> overflow-hidden"><div class="border-b border-slate-200 px-5 py-5"><p class="text-[11px] font-bold uppercase tracking-[0.15em] text-slate-500">12 tháng gần nhất</p><h3 class="mt-1 text-lg font-bold text-slate-950">Doanh thu theo tháng</h3></div><?php if (empty($metrics['monthly'])): ?><p class="p-5 text-sm text-slate-500">Chưa có dữ liệu doanh thu.</p><?php else: ?><?php $rows = []; foreach ($metrics['monthly'] as $row) { $rows[] = [ViewHelper::escape($row['period']), (int)$row['orders'], ViewHelper::money((int)$row['revenue'])]; } $table(['Tháng', 'Đơn', 'Doanh thu'], $rows); ?><?php endif; ?></section>
    </div>

    <div class="grid gap-6 xl:grid-cols-2">
        <section class="<?= $panel ?> overflow-hidden"><div class="border-b border-slate-200 px-5 py-5"><p class="text-[11px] font-bold uppercase tracking-[0.15em] text-slate-500">Sản phẩm</p><h3 class="mt-1 text-lg font-bold text-slate-950">Sách bán chạy</h3></div><?php if (empty($metrics['topBooks'])): ?><p class="p-5 text-sm text-slate-500">Chưa có dữ liệu bán sách.</p><?php else: ?><?php $rows = []; foreach ($metrics['topBooks'] as $row) { $rows[] = [ViewHelper::escape($row['book_title']), (int)$row['quantity'], ViewHelper::money((int)$row['revenue'])]; } $table(['Sách', 'Số lượng', 'Doanh thu'], $rows); ?><?php endif; ?></section>
        <section class="<?= $panel ?> overflow-hidden"><div class="flex items-end justify-between gap-4 border-b border-slate-200 px-5 py-5"><div><p class="text-[11px] font-bold uppercase tracking-[0.15em] text-slate-500">Vận hành</p><h3 class="mt-1 text-lg font-bold text-slate-950">Đơn hàng gần đây</h3></div><a href="/admin/orders" class="text-sm font-semibold text-orange-700 hover:text-orange-800">Xem tất cả</a></div><?php if (empty($metrics['recentOrders'])): ?><p class="p-5 text-sm text-slate-500">Chưa có đơn hàng.</p><?php else: ?><?php $rows = []; foreach ($metrics['recentOrders'] as $row) { $rows[] = [ViewHelper::escape($row['order_code']), ViewHelper::escape($row['customer_name']), ViewHelper::money((int)$row['total']), ViewHelper::escape(ViewHelper::orderStatus((string)$row['status']))]; } $table(['Mã đơn', 'Khách hàng', 'Tổng', 'Trạng thái'], $rows); ?><?php endif; ?></section>
    </div>
</div>